#!/bin/sh
set -eu

ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
cd "$ROOT"

if [ "$(id -u)" -ne 0 ]; then
    echo "Run with sudo: sudo ./scripts/build-iso.sh" >&2
    exit 1
fi

command -v lb >/dev/null 2>&1 || {
    echo "live-build is missing. Run ./scripts/install-dependencies.sh first." >&2
    exit 1
}

configure_build() {
    # These files are generated by live-build and may contain stale values.
    rm -f config/binary config/bootstrap config/chroot config/common config/source
    rm -f config/package-lists/live.list.chroot
    # Live-build adds default hook symlinks here; a failed or repeated config
    # must not leave them behind for the next mirror attempt.
    if [ -d config/hooks ]; then
        find config/hooks -type l -delete
    fi
    # Some Docker Desktop/Windows bind-mount combinations materialize those
    # generated links as ordinary files, so remove the known Live Build hook
    # destinations as well. Keep project hooks, which use their own names.
    if [ -d /usr/share/live/build/hooks/normal ]; then
        for default_hook in /usr/share/live/build/hooks/normal/*; do
            [ -e "$default_hook" ] || continue
            rm -f -- "config/hooks/normal/$(basename "$default_hook")"
        done
    fi
    lb config
}

mkdir -p build
mirror_pairs=${DEVOS_DEBIAN_MIRRORS:-http://mirror.iranserver.com/debian/\|http://mirror.iranserver.com/debian-security/,http://mirror.arvancloud.ir/debian/\|http://mirror.arvancloud.ir/debian-security/,http://mirror.famaserver.com/debian/\|http://mirror.iranserver.com/debian-security/,http://deb.debian.org/debian/\|http://security.debian.org/debian-security/}
success=0
for pair in $(printf '%s' "$mirror_pairs" | tr ',' '\n'); do
    export DEVOS_DEBIAN_MIRROR=${pair%%|*}
    export DEVOS_SECURITY_MIRROR=${pair#*|}
    echo "Building with Debian mirrors: $DEVOS_DEBIAN_MIRROR and $DEVOS_SECURITY_MIRROR"
    lb clean --all
    configure_build
    if lb build; then
        success=1
        break
    fi
    echo "Debian mirror pair failed; trying the next configured pair." >&2
done
if [ "$success" -ne 1 ]; then
    echo "All configured Debian mirror pairs failed." >&2
    exit 1
fi

set -- ./*.iso
if [ ! -f "$1" ]; then
    echo "Build completed but no ISO was found." >&2
    exit 1
fi
mv -- "$1" build/devos-amd64.iso
echo "Created: $ROOT/build/devos-amd64.iso"
